        gap: 0.7rem;
        color: var(--color-text);
        font-weight: 800;
        letter-spacing: -0.02em;
        text-decoration: none;
      }

      .brand-mark {
        display: grid;
        width: 2.5rem;
        height: 2.5rem;
        place-items: center;
        border-radius: 0.9rem;
        background: var(--color-primary);
        color: #ffffff;
      }

      .page-shell {
        display: grid;
        min-height: calc(100vh - 5rem);
        place-items: center;
        padding: 2rem clamp(1rem, 4vw, 3rem) 4rem;
      }

      .support-card {
        display: grid;
        grid-template-columns: minmax(0, 0.88fr) minmax(18rem, 1fr);
        gap: clamp(1.25rem, 4vw, 3rem);
        width: min(100%, 64rem);
        border: 1px solid #d9e0ea;
        border-radius: var(--radius-lg);
        background: var(--color-surface);
        box-shadow: var(--shadow-card);
        overflow: hidden;
      }

      .intro-panel {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        gap: 2rem;
        min-width: 0;
        padding: clamp(2rem, 5vw, 4rem);
        background: linear-gradient(145deg, #10233f 0%, #172b52 58%, #155eef 100%);
        color: #ffffff;
      }

      .eyebrow {
        margin: 0 0 1rem;
        color: #cfe0ff;
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        max-width: 12ch;
        margin: 0;
        font-size: clamp(2.4rem, 8vw, 4.75rem);
        line-height: 0.95;
        letter-spacing: -0.07em;
      }

      .intro-copy {
        max-width: 32rem;
        margin: 1.3rem 0 0;
        color: #e7efff;
        font-size: 1.05rem;
      }

      .support-meta {
        display: grid;
        gap: 0.9rem;
        margin: 0;
      }

      .support-meta div {
        display: grid;
        gap: 0.15rem;
      }

      .support-meta dt {
        color: #cfe0ff;
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      .support-meta dd {
        margin: 0;
        color: #ffffff;
        font-weight: 700;
      }

      .form-panel {
        min-width: 0;
        padding: clamp(2rem, 5vw, 4rem);
      }

      .form-heading {
        margin: 0 0 0.35rem;
        font-size: clamp(1.55rem, 4vw, 2rem);
        line-height: 1.15;
        letter-spacing: -0.04em;
      }

      .form-note {
        margin: 0 0 1.8rem;
        color: var(--color-muted);
      }

      .contact-form {
        display: grid;
        gap: 1.15rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      label {
        color: var(--color-text);
        font-size: 0.94rem;
        font-weight: 800;
      }

      .required-note,
      .optional-note {
        color: var(--color-muted);
        font-size: 0.9rem;
        font-weight: 700;
      }

      input {
        width: 100%;
        min-height: 3.25rem;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-md);
        background: #ffffff;
        color: var(--color-text);
        padding: 0.85rem 1rem;
        font: inherit;
      }

      input::placeholder {
        color: #687789;
      }

      input:hover {
        border-color: var(--color-border-strong);
      }

      input:focus {
        border-color: var(--color-primary);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--color-focus);
      }

      input[aria-invalid="true"] {
        border-color: var(--color-danger);
      }

      .helper-text,
      .error-message {
        margin: 0;
        font-size: 0.9rem;
      }

      .helper-text {
        color: var(--color-muted);
      }

      .error-message {
        color: var(--color-danger);
        font-weight: 700;
      }

      .submit-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-height: 3.35rem;
        margin-top: 0.35rem;
        border: 1px solid var(--color-primary);
        border-radius: var(--radius-md);
        background: var(--color-primary);
        color: #ffffff;
        padding: 0.85rem 1.25rem;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      .submit-button:hover {
        background: var(--color-primary-hover);
        border-color: var(--color-primary-hover);
      }

      .submit-button:active {
        background: var(--color-primary-active);
        border-color: var(--color-primary-active);
      }

      .submit-button:focus {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--color-focus);
      }

      .form-status {
        min-height: 1.5rem;
        margin: 0.35rem 0 0;
        color: var(--color-success);
        font-weight: 800;
      }

      @media (max-width: 760px) {
        .support-card {
          grid-template-columns: 1fr;
        }

        .intro-panel {
          padding-bottom: 2.5rem;
        }

        h1 {
          max-width: 11ch;
        }
      }

      @media (forced-colors: active) {
        .brand-mark,
        .intro-panel,
        .submit-button,
        .skip-link {
          border: 1px solid ButtonBorder;
          background: Canvas;
          color: CanvasText;
        }

        input,
        .support-card {
          border-color: ButtonBorder;
        }

        input:focus,
        .submit-button:focus,
        .skip-link:focus {
          outline: 3px solid ButtonText;
          box-shadow: none;
        }
      }
