  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <header class="site-header">
      <a class="brand" href="#" aria-label="Acme Support home">
        <span class="brand-mark" aria-hidden="true">A</span>
        <span>Acme Support</span>
      </a>
    </header>

    <main id="main-content" class="page-shell">
      <section class="support-card" aria-labelledby="support-title">
        <div class="intro-panel">
          <div>
            <p class="eyebrow">Support center</p>
            <h1 id="support-title">How can we help?</h1>
            <p class="intro-copy">
              Tell us how to reach you and a product specialist will follow up with the right next step.
            </p>
          </div>

          <dl class="support-meta" aria-label="Support details">
            <div>
              <dt>Response time</dt>
              <dd>Usually within one business day</dd>
            </div>
            <div>
              <dt>Coverage</dt>
              <dd>Billing, account, and product support</dd>
            </div>
          </dl>
        </div>

        <div class="form-panel">
          <h2 class="form-heading">Contact support</h2>
          <p class="form-note">Fields marked required must be completed before submitting.</p>

          <form class="contact-form" id="contact-form" novalidate>
            <div class="form-field">
              <label for="full-name">Full name <span class="required-note">(required)</span></label>
              <input id="full-name" name="fullName" type="text" autocomplete="name" required>
            </div>

            <div class="form-field">
              <label for="email-address">Email address <span class="required-note">(required)</span></label>
              <input id="email-address" name="email" type="email" autocomplete="email" required>
            </div>

            <div class="form-field">
              <label for="phone-number">Phone number <span class="optional-note">(optional)</span></label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                autocomplete="tel"
                inputmode="tel"
                aria-describedby="phone-helper"
              >
              <p class="helper-text" id="phone-helper">Use a format like +1 555 123 4567 or (555) 123-4567.</p>
            </div>

            <button class="submit-button" type="submit">Submit support request</button>
            <p class="form-status" id="form-status" aria-live="polite"></p>
          </form>
        </div>
      </section>
    </main>

    <script>
      const form = document.querySelector("#contact-form");
      const statusMessage = document.querySelector("#form-status");
      const fields = [
        {
          input: document.querySelector("#full-name"),
          validate(value) {
            return value.trim() ? "" : "Enter your full name.";
          }
        },
        {
          input: document.querySelector("#email-address"),
          validate(value) {
            if (!value.trim()) {
              return "Enter your email address.";
            }

            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
              ? ""
              : "Enter an email address in the format name@example.com.";
          }
        },
        {
          input: document.querySelector("#phone-number"),
          helperId: "phone-helper",
          validate(value) {
            if (!value.trim()) {
              return "";
            }

            return /^[+()0-9\s.-]{7,20}$/.test(value.trim())
              ? ""
              : "Enter a phone number using numbers, spaces, parentheses, periods, hyphens, or a plus sign.";
          }
        }
      ];

      function getErrorId(input) {
        return `${input.id}-error`;
      }

      function setFieldError(field, message) {
        const { input, helperId } = field;
        const errorId = getErrorId(input);
        let errorMessage = document.querySelector(`#${errorId}`);

        if (!message) {
          input.removeAttribute("aria-invalid");
          errorMessage?.remove();
          input.setAttribute("aria-describedby", helperId || "");
          if (!helperId) {
            input.removeAttribute("aria-describedby");
          }
          return;
        }

        input.setAttribute("aria-invalid", "true");

        if (!errorMessage) {
          errorMessage = document.createElement("p");
          errorMessage.className = "error-message";
          errorMessage.id = errorId;
          input.insertAdjacentElement("afterend", errorMessage);
        }

        errorMessage.textContent = message;
        input.setAttribute("aria-describedby", [helperId, errorId].filter(Boolean).join(" "));
      }

      fields.forEach((field) => {
        field.input.addEventListener("input", () => {
          if (field.input.getAttribute("aria-invalid") === "true") {
            setFieldError(field, field.validate(field.input.value));
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        statusMessage.textContent = "";

        const invalidFields = fields
          .map((field) => {
            const message = field.validate(field.input.value);
            setFieldError(field, message);
            return message ? field.input : null;
          })
          .filter(Boolean);

        if (invalidFields.length) {
          invalidFields[0].focus();
          return;
        }

        form.reset();
        fields.forEach((field) => setFieldError(field, ""));
        statusMessage.textContent = "Your support request is ready to send.";
      });
    </script>
  </body>
</html>
